<?php
declare(strict_types=1);
/**
 * One-shot installer. Open /install_bundle.php?key=INSTALL_KEY then delete this file.
 */
$EXPECTED = 'rm-install-7f3a';
$key = $_GET['key'] ?? '';
if (!hash_equals($EXPECTED, (string)$key)) {
    http_response_code(403);
    echo 'Forbidden';
    exit;
}
$files = json_decode("{\".htaccess\":\"\",\"config.sample.php\":\"\",\"index.php\":\"\",\"router.php\":\"\",\"DEPLOY.md\":\"\",\"data/.htaccess\":\"UmVxdWlyZSBhbGwgZGVuaWVkCg==\",\"data/.gitkeep\":\"\",\"views/dashboard.php\":\"\",\"views/home.php\":\"\",\"views/login.php\":\"\",\"views/tool_form.php\":\"\",\"views/layout.php\":\"\",\"views/register.php\":\"\",\"views/brief_show.php\":\"\",\"views/upgrade.php\":\"\",\"assets/app.css\":\"\",\"storage/.htaccess\":\"UmVxdWlyZSBhbGwgZGVuaWVkCg==\",\"lib/.htaccess\":\"UmVxdWlyZSBhbGwgZGVuaWVkCg==\",\"lib/helpers.php\":\"\",\"lib/bootstrap.php\":\"\",\"lib/auth.php\":\"\",\"lib/llm.php\":\"\",\"lib/db.php\":\"\",\"lib/tools.php\":\"\",\"lib/plans.php\":\"\",\"storage/uploads/.gitkeep\":\"\"}", true);
if (!is_array($files)) {
    http_response_code(500);
    echo 'Bad bundle';
    exit;
}
$base = __DIR__;
$written = [];
foreach ($files as $rel => $b64) {
    $path = $base . '/' . $rel;
    $dir = dirname($path);
    if (!is_dir($dir) && !mkdir($dir, 0775, true) && !is_dir($dir)) {
        throw new RuntimeException('mkdir failed: ' . $dir);
    }
    $bytes = base64_decode($b64, true);
    if ($bytes === false) {
        throw new RuntimeException('decode failed: ' . $rel);
    }
    if (file_put_contents($path, $bytes) === false) {
        throw new RuntimeException('write failed: ' . $rel);
    }
    $written[] = $rel . ' (' . strlen($bytes) . ')';
}
// create config.php if missing
$cfgPath = $base . '/config.php';
if (!is_file($cfgPath)) {
    $setup = 'rm-' . bin2hex(random_bytes(6));
    $cfg = "<?php\nreturn [\n"
        . "  'app_name' => 'Realmatics',\n"
        . "  'app_url' => '',\n"
        . "  'admin_email' => 'hello@realmatics.example',\n"
        . "  'openai_api_key' => '',\n"
        . "  'openai_base_url' => 'https://api.openai.com/v1',\n"
        . "  'openai_model' => 'gpt-4o-mini',\n"
        . "  'admin_setup_key' => '" . $setup . "',\n"
        . "  'stripe_payment_link_team' => '',\n"
        . "  'stripe_payment_link_pro' => '',\n"
        . "];\n";
    file_put_contents($cfgPath, $cfg);
    $written[] = 'config.php (generated, setup_key=' . $setup . ')';
}
@unlink($base . '/index.html');
header('Content-Type: text/plain; charset=utf-8');
echo "OK installed " . count($written) . " files\n\n";
echo implode("\n", $written);
echo "\n\nDelete install_bundle.php now.\n";
